import { useState, useCallback, useRef } from "react";

const IMG_BR = "data:image/jpeg;base64,";
const IMG_MY = "data:image/jpeg;base64,";

/* ── TOKENS ─────────────────────────────────────────── */
const C = {
  bg:     "#FAFAF8",
  paper:  "#FFFFFF",
  ink:    "#111111",
  red:    "#C8002A",
  gold:   "#B8860B",
  panel:  "#F5F2EE",
  border: "#E0DDD8",
  subtle: "#888880",
  green:  "#1a5c1a",
  blue:   "#0a3a6a",
  lgreen: "#f0f7f0",
  lblue:  "#f0f4f8",
  lred:   "#fff8f8",
  bgreen: "#b0d8b0",
  bblue:  "#b0c8e0",
  bred:   "#ffd0d0",
};

/* ── FONTS ───────────────────────────────────────────── */
const FONTS = `@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Noto+Serif:ital,wght@0,400;0,700;1,400;1,700&family=IBM+Plex+Mono:wght@400;500&display=swap');`;

/* ── GLOBAL CSS ──────────────────────────────────────── */
const CSS = `
${FONTS}
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { -webkit-text-size-adjust: 100%; }
body { background: ${C.bg}; overscroll-behavior: none; }

@keyframes sIn {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}
.sIn { animation: sIn .32s ease forwards; }

/* slide wrapper — full viewport height, no scroll */
.deck {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  background: ${C.bg};
  user-select: none;
  -webkit-user-select: none;
  touch-action: pan-y;
}

/* content area takes all available space above nav */
.slide-area {
  flex: 1;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.slide {
  flex: 1;
  background: ${C.paper};
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* top bar */
.sbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 18px;
  background: ${C.panel};
  border-bottom: 1px solid ${C.border};
  flex-shrink: 0;
}
.sbar-l { font-family: 'IBM Plex Mono', monospace; font-size: 9px;
           letter-spacing: .12em; color: ${C.subtle}; }
.sbar-r { font-family: 'IBM Plex Mono', monospace; font-size: 9px;
           letter-spacing: .12em; color: ${C.red}; }

/* scrollable content within a slide */
.scontent {
  flex: 1;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 20px 18px 16px;
}

/* nav bar */
.nav {
  display: flex;
  align-items: center;
  padding: 10px 14px;
  gap: 12px;
  background: ${C.paper};
  border-top: 1px solid ${C.border};
  flex-shrink: 0;
}
.nbtn {
  flex-shrink: 0;
  background: none;
  border: 1.5px solid ${C.border};
  color: ${C.subtle};
  font-family: 'IBM Plex Mono', monospace;
  font-size: 13px;
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  border-radius: 4px;
  transition: all .15s;
  -webkit-tap-highlight-color: transparent;
}
.nbtn:active { border-color: ${C.red}; color: ${C.red}; background: ${C.panel}; }
.nbtn:disabled { opacity: .18; }
.ndots {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  justify-content: center;
  align-items: center;
}
.ndot {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: ${C.border};
  cursor: pointer;
  transition: all .15s;
  -webkit-tap-highlight-color: transparent;
  flex-shrink: 0;
}
.ndot.on { background: ${C.red}; transform: scale(1.35); }
.nctr {
  flex-shrink: 0;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px;
  color: ${C.border};
  letter-spacing: .08em;
  min-width: 36px;
  text-align: right;
}

/* typography */
.title {
  font-family: 'Bebas Neue', sans-serif;
  font-size: clamp(32px, 9vw, 52px);
  line-height: 1;
  color: ${C.ink};
  letter-spacing: .01em;
}
.title-red { color: ${C.red}; }
.subtitle {
  font-family: 'Noto Serif', serif;
  font-style: italic;
  font-size: clamp(16px, 4.5vw, 22px);
  color: ${C.red};
  line-height: 1.2;
  margin-top: 4px;
}
.body {
  font-family: 'Noto Serif', serif;
  font-size: clamp(13px, 3.5vw, 16px);
  line-height: 1.75;
  color: #444;
}
.mono {
  font-family: 'IBM Plex Mono', monospace;
  font-size: clamp(9px, 2.5vw, 11px);
  letter-spacing: .1em;
  color: ${C.subtle};
  text-transform: uppercase;
}
.mono-red { color: ${C.red}; }

/* rule */
.rule { width: 36px; height: 2px; background: ${C.red}; margin: 14px 0; }

/* tag row */
.tag {
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 10px;
}
.tag-dash { width: 16px; height: 1.5px; background: ${C.red}; }

/* stat */
.stat-num {
  font-family: 'Bebas Neue', sans-serif;
  font-size: clamp(36px, 10vw, 56px);
  color: ${C.red}; line-height: 1;
}
.stat-label {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px; color: ${C.subtle};
  letter-spacing: .1em; text-transform: uppercase;
  margin-top: 2px;
}

/* card */
.card {
  background: ${C.panel};
  border: 1px solid ${C.border};
  padding: 14px 16px;
}
.card-accent { border-top: 2.5px solid ${C.red}; }
.card-accent-green { border-top: 2.5px solid ${C.green}; }
.card-accent-gold  { border-top: 2.5px solid ${C.gold};  }

/* buff chip */
.buff {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; letter-spacing: .08em; text-transform: uppercase;
  padding: 5px 12px; color: white;
}

/* place list */
.plist { border: 1px solid ${C.border}; overflow: hidden; margin-top: 12px; }
.prow {
  display: flex; justify-content: space-between; align-items: center;
  padding: 10px 12px;
  border-bottom: 1px solid ${C.border};
  gap: 8px;
}
.prow:last-child { border-bottom: none; }
.prow:nth-child(even) { background: ${C.panel}; }
.prow-name {
  font-family: 'Noto Serif', serif;
  font-weight: 700;
  font-size: clamp(12px, 3.2vw, 14px);
  color: ${C.ink};
}
.prow-detail {
  font-family: 'IBM Plex Mono', monospace;
  font-size: clamp(9px, 2.3vw, 10px);
  color: ${C.subtle};
  text-align: right;
  flex-shrink: 0;
}

/* blockquote */
.bq {
  border-left: 3px solid ${C.border};
  padding: 10px 14px;
  font-family: 'Noto Serif', serif;
  font-style: italic;
  font-size: clamp(13px, 3.5vw, 15px);
  color: ${C.subtle};
  line-height: 1.65;
  background: ${C.panel};
  margin-top: 12px;
}
.bq-footer {
  margin-top: 8px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px; font-style: normal;
  letter-spacing: .06em;
}

/* village seal */
.vseal {
  width: 52px; height: 52px;
  border: 2.5px solid ${C.red};
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Noto Serif', serif;
  font-size: 20px; color: ${C.red};
  position: relative; flex-shrink: 0;
}
.vseal::before {
  content: ''; position: absolute; inset: 5px;
  border: 1px solid ${C.red}; border-radius: 50%; opacity: .4;
}

/* grid texture overlay */
.gtex {
  position: absolute; inset: 0; pointer-events: none; z-index: 0;
  background-image:
    linear-gradient(${C.ink} 1px, transparent 1px),
    linear-gradient(90deg, ${C.ink} 1px, transparent 1px);
  background-size: 32px 32px;
  opacity: .025;
}

/* TBC arrow */
.tbc {
  display: flex; align-items: center; gap: 10px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px; letter-spacing: .16em;
  color: ${C.red}; text-transform: uppercase;
  margin-top: 16px;
}

/* corner marks */
.corners {
  position: absolute; inset: 12px; pointer-events: none; z-index: 1;
}
.corner {
  position: absolute;
  width: 18px; height: 18px;
  border-color: ${C.red}; border-style: solid;
}
.corner-tl { top:0; left:0; border-width: 2px 0 0 2px; }
.corner-tr { top:0; right:0; border-width: 2px 2px 0 0; }
.corner-bl { bottom:0; left:0; border-width: 0 0 2px 2px; }
.corner-br { bottom:0; right:0; border-width: 0 2px 2px 0; }

/* row layout for stats */
.row { display: flex; gap: 12px; flex-wrap: wrap; align-items: flex-start; }
.row-center { align-items: center; }

/* comparison panels */
.cmp { flex: 1; min-width: 140px; padding: 14px 14px; }

/* schedule item */
.sched-item {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid ${C.border};
}
.sched-h {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 22px; color: ${C.red};
  min-width: 38px; line-height: 1.1; flex-shrink: 0;
}
.sched-l {
  font-family: 'Noto Serif', serif;
  font-size: clamp(12px, 3.2vw, 14px);
  color: ${C.ink}; padding-top: 3px; line-height: 1.5;
}

/* guide grid */
.guide-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 10px;
}
.guide-card {
  border: 1px solid ${C.border};
  border-top: 2px solid ${C.red};
  padding: 10px 12px;
  background: ${C.panel};
}
.guide-title {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9.5px; font-weight: 500;
  letter-spacing: .08em;
  margin-bottom: 8px;
}
.guide-item {
  font-family: 'Noto Serif', serif;
  font-size: clamp(11px, 3vw, 13px);
  padding: 3px 0;
  border-bottom: 1px solid ${C.border};
  color: ${C.ink};
}
.guide-item:last-child { border-bottom: none; }

/* member block */
.member {
  display: flex; gap: 10px; align-items: flex-start;
  margin-bottom: 16px;
}
.member-dot {
  width: 10px; height: 10px; border-radius: 50%;
  flex-shrink: 0; margin-top: 5px;
}
`;

