const S04 = () => {
  const mapRef = useRef(null);
  const instRef = useRef(null);
  const [mapReady, setMapReady] = useState(false);

  const initMap = useCallback(() => {
    if (!mapRef.current || instRef.current) return;
    const L = window.L;
    const map = L.map(mapRef.current, { zoomControl: false, scrollWheelZoom: false, attributionControl: false })
      .setView([-30.0267, -51.1919], 16);
    instRef.current = map;
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", { maxZoom: 19 }).addTo(map);
    const mk = (col, label) => L.divIcon({ className: "",
      html: `<div style="background:${col};color:#fff;font-family:monospace;font-size:10px;padding:3px 7px;white-space:nowrap;border-radius:2px;box-shadow:0 2px 6px rgba(0,0,0,.25)">${label}</div>`,
      iconAnchor: [0, 0] });
    L.marker([-30.025879,-51.191561], { icon: mk(C.blue,"Bruno & Raquel") }).addTo(map);
    L.marker([-30.027458,-51.192322], { icon: mk(C.green,"Menegotto & Yas") }).addTo(map);
    map.fitBounds([[-30.025879,-51.191561],[-30.027458,-51.192322]], { padding: [50,50] });
    setMapReady(true);
  }, []);

  const loadMap = useCallback((node) => {
    if (!node) return;
    mapRef.current = node;
    if (window.L) { initMap(); return; }
    const lk = document.createElement("link"); lk.rel = "stylesheet";
    lk.href = "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css";
    document.head.appendChild(lk);
    const sc = document.createElement("script");
    sc.src = "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js";
    sc.onload = initMap; document.head.appendChild(sc);
  }, [initMap]);

  return (
    <S num="04" topic="A VILA">
      <Tag ch="membros fundadores" />
      <div className="title">A Vila</div>
      <div className="subtitle">Mont Serrat</div>
      <Rule />
      {[
        [C.green, "Menegotto & Yas", "R. Anita Garibaldi, 359", "Primeiros Desbravadores · Março 2026"],
        [C.blue,  "Bruno & Raquel",  "R. Fabrício Pilar, 571",  "Co-fundadores & Agitadores · Abril 2026"],
      ].map(([col, name, addr, role]) => (
        <div className="member" key={name}>
          <div className="member-dot" style={{ background: col }} />
          <div>
            <div style={{ fontFamily: "'Noto Serif',serif", fontWeight: 700, fontSize: 15 }}>{name}</div>
            <div className="mono" style={{ marginTop: 2 }}>{addr}</div>
            <div className="mono mono-red" style={{ marginTop: 1 }}>{role}</div>
          </div>
        </div>
      ))}
      <div style={{ display: "inline-flex", alignItems: "center", gap: 12,
                    background: C.panel, padding: "10px 16px",
                    border: `1px solid ${C.border}`, marginBottom: 14 }}>
        <span style={{ fontFamily: "'Bebas Neue',sans-serif", fontSize: 22, color: C.red }}>≈ 250m</span>
        <span className="mono">entre as casas</span>
      </div>
      <div ref={loadMap} style={{
        height: 240, border: `1px solid ${C.border}`,
        filter: "grayscale(15%) contrast(0.95)",
        background: C.panel,
      }} />
    </S>
  );
};

